//! Disposable benchmark of existing control sends and metacircular lookup.
#[path = "../tests/support/oop.rs"]
mod oop;
use birnam_abi::size;
unsafe extern "C" { fn clock_gettime_nsec_np(clock: u32) -> u64; }
fn main() {
    let h = oop::bootstrap();
    let q = h.scope();
    let fixture = h.load_native(&q, &std::path::PathBuf::from(std::env::args().nth(1).unwrap()), &[]).unwrap();
    let selector = q.keep(h.intern(b"probe").unwrap()).unwrap();
    let method = q.call(fixture, b"methodAt:", &[selector]).unwrap();
    let receiver = q.call(h.named(b"Object").unwrap(), b"clone", &[]).unwrap();
    let vt = q.call(h.id.root, b"ensurePrivateVtableFor:", &[receiver]).unwrap();
    q.call(vt, b"addMethod", &[selector, method]).unwrap();
    if std::env::args().nth(2).as_deref() == Some("custom") {
        let lookup = q.keep(h.intern(b"lookup").unwrap()).unwrap();
        let meta = q.call(h.id.root, b"behaviorOf:", &[vt]).unwrap();
        let original = q.call(meta, b"lookup", &[lookup]).unwrap();
        let new_meta = q.call(meta, b"delegated", &[]).unwrap();
        let entry = q.call(fixture, b"methodAt:", &[q.keep(h.intern(b"forwardLookup").unwrap()).unwrap()]).unwrap();
        let forward = q.call(entry, b"withContext:", &[original]).unwrap();
        q.call(new_meta, b"addMethod", &[lookup, forward]).unwrap();
        q.call(h.id.root, b"reassociateBehaviorOf:with:", &[vt, new_meta]).unwrap();
    }
    let gc = h.named(b"GC").unwrap();
    q.call(gc, b"automaticCollection:", &[size(0).unwrap()]).unwrap();
    for arity in [0, 1, 8, 64] {
        let args: Vec<_> = std::iter::once(size(512).unwrap())
            .chain((1..=arity).map(|i| size(i).unwrap())).collect();
        let expected = if arity == 0 {receiver} else {size(arity).unwrap()};
        assert_eq!(unsafe { h.id.send(receiver, selector, &args).unwrap() }, expected);
        for _ in 0..7 {
            q.call(gc, b"collectPrecisely", &[]).unwrap();
            let start = unsafe { clock_gettime_nsec_np(16) };
            for _ in 0..4 { assert_eq!(unsafe { h.id.send(receiver, selector, &args).unwrap() }, expected); }
            println!("{arity} {}", unsafe { clock_gettime_nsec_np(16) } - start);
        }
    }
}

