#include "id.h"
static IdContinuationProtocol api;
static Oop names[5];
static Oop probe(Oop root,Oop context,Oop receiver,const Oop *a,size_t n) {
 (void)root;(void)context;
 if(n<2||n>66)return id_failure(api.common.invalid);
 for(size_t i=2;i<n;i++)if(a[i]!=id_size(i-1))return id_failure(api.common.invalid);
 size_t remaining=id_unbox(a[1]);
 if(!remaining){Oop result[]={a[0],n==2?receiver:a[n-1]};return api.control(api.common.root,names[1],result,2);}
 Oop next[68]={receiver,names[0],a[0],id_size(remaining-1)};
 for(size_t i=2;i<n;i++)next[i+2]=a[i];
 return api.control(api.common.root,names[2],next,n+2);
}
static Oop lookup(Oop root,Oop context,Oop receiver,const Oop *a,size_t n) {
 (void)root;if(n!=2)return id_failure(api.common.invalid);
 Oop entry[]={context,receiver,a[0],a[1]};return api.control(api.common.root,names[3],entry,4);
}
static Oop initialize(const IdContinuationProtocol *p,Oop image,const Oop *s,size_t n,const Oop *a,size_t count) {
 (void)a;if(n!=5||count)return id_failure(p->common.invalid);api=*p;for(size_t i=0;i<n;i++)names[i]=s[i];return image;
}
static const IdLiteral literals[]={LIT("probe"),LIT("answerTo:with:"),LIT("prepareSend"),LIT("prepareEntry"),LIT("forwardLookup")};
